class ModificaProdottoMenuApp(QMainWindow):
    def __init__(self):
        super().__init__()
        self.ui = Ui_Form()
        self.ui.setupUi(self)
        # Connessione al database MySQL
        self.conn = mysql.connector.connect(
            host='localhost',
            database='dbristorante',
            user='root',
            password='1234'
        )
        # Popola la QListWidget con i dati dal database
        self.popola_lista_elemento()

    def popola_lista_elemento(self):
        # Crea il cursore per eseguire query
        cursor = self.conn.cursor()

        try:
            # Query per selezionare la colonna 'nome' dalla tabella 'nomeelemento'
            query = "SELECT nome FROM nomeelemento"
            cursor.execute(query)

            # Ottieni tutti i risultati dalla query
            result = cursor.fetchall()

            # Popola la QListWidget con i risultati della query
            for row in result:
                nome_elemento = row[0]  # Assume che 'nome' sia la prima colonna nella query
                self.ui.listWidget_nome_elemento.addItem(nome_elemento)

        except mysql.connector.Error as err:
            print(f"Errore durante l'esecuzione della query: {err}")

        finally:
            # Chiudi il cursore e la connessione
            cursor.close()
            self.conn.close()


